            if i != j:
                ang = angle(fruits[i], fruits[j])
                if ang in angles:
                    angles[ang] += 1
                else:
                    angles[ang] = 1
        if angles:
            max_count = max(max_count, max(angles.values()))

    return max_count + 1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    fruits = []
    index = 1
    for _ in range(n):
        x = float(data[index])
        y = float(data[index + 1])
        fruits.append((x, y))
        index += 2

    result = max_fruits_sliced(n, fruits)
    print(result)

if __name__ == "__main__":
